WITH valid AS (SELECT id, reading_ts, temp_c, pressure, status_bits, ROUND(humidity / temp_c, 2) humidity_per_temp_c FROM device_readings WHERE temp_c BETWEEN 29 AND 38), filtered AS (SELECT *, DATE_TRUNC('month', reading_ts) reading_ts_period, humidity_per_temp_c - pressure humidity_per_temp_c_minus_pressure FROM valid WHERE temp_c < 26), metrics AS (SELECT *, PERCENT_RANK() OVER (ORDER BY humidity_per_temp_c DESC NULLS FIRST) humidity_per_temp_c_percent_rank, LAST_VALUE(humidity_per_temp_c) IGNORE NULLS OVER w_recent last_known_humidity_per_temp_c, FIRST_VALUE(humidity_per_temp_c) IGNORE NULLS OVER w_recent_2 first_known_humidity_per_temp_c FROM filtered WINDOW w_recent AS (ORDER BY temp_c, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW), w_recent_2 AS (ORDER BY status_bits, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW)), enriched AS (SELECT *, COUNT(temp_c) OVER (ORDER BY CAST(reading_ts_period AS BIGINT) RANGE BETWEEN 7776000 PRECEDING AND CURRENT ROW) temp_c_count_90d, FIRST_VALUE(last_known_humidity_per_temp_c, TRUE) OVER (ORDER BY humidity_per_temp_c, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) first_known_last_known_humidity_per_temp_c, CUME_DIST() OVER (ORDER BY humidity_per_temp_c_percent_rank DESC) humidity_per_temp_c_percent_rank_cume_dist, FIRST_VALUE(pressure, TRUE) OVER (ORDER BY first_known_humidity_per_temp_c, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) first_known_pressure, FIRST_VALUE(humidity_per_temp_c) IGNORE NULLS OVER (ORDER BY pressure, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) first_known_humidity_per_temp_c_2 FROM metrics), metrics_device_readings AS (SELECT *, PERCENT_RANK() OVER (ORDER BY temp_c_count_90d NULLS FIRST) temp_c_count_90d_percent_rank, AVG(first_known_humidity_per_temp_c_2) OVER (ORDER BY reading_ts_period, id ROWS BETWEEN 3 PRECEDING AND 1 PRECEDING) first_known_humidity_per_temp_c_2_avg_3_prior, ROW_NUMBER() OVER (ORDER BY temp_c_count_90d DESC, id) row_seq, RANK() OVER (ORDER BY first_known_pressure NULLS FIRST) first_known_pressure_rank, LAG(temp_c, 1) OVER (ORDER BY temp_c, id) prev_temp_c FROM enriched), enriched_device_readings AS (SELECT *, SUM(first_known_pressure_rank) OVER (ORDER BY first_known_pressure_rank, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) cumulative_first_known_pressure_rank, ROW_NUMBER() OVER (ORDER BY row_seq, id) seq_no, LEAD(temp_c, 1) OVER (ORDER BY last_known_humidity_per_temp_c, id) next_temp_c FROM metrics_device_readings), with_windows AS (SELECT *, LAG(humidity_per_temp_c_minus_pressure, 1) OVER (ORDER BY first_known_humidity_per_temp_c_2, id) prev_humidity_per_temp_c_minus_pressure, ROW_NUMBER() OVER (ORDER BY first_known_pressure, id) seq_no_2, SUM(first_known_pressure_rank) OVER (ORDER BY row_seq, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) running_first_known_pressure_rank FROM enriched_device_readings) SELECT *, AVG(humidity_per_temp_c_minus_pressure) OVER w_running humidity_per_temp_c_minus_pressure_avg_3, LEAD(temp_c, 2) OVER w_part next_temp_c_2 FROM with_windows WINDOW w_running AS (ORDER BY pressure, id ROWS BETWEEN 3 PRECEDING AND CURRENT ROW), w_part AS (ORDER BY reading_ts_period, id)
